      fetchtotalcount: false(),
      query: #"SYSTEM_SYSRULES_query"(
        selection: #"SYSTEM_SYSRULES_querySelection"(columns: { #"SYSTEM_SYSRULES_queryColumn"(field: "descr") }),
        paginginfo: #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: 1,
          batchSize: - 1,
          sort: #"SYSTEM_SYSRULES_sortInfo"(field: "location", ascending: true)
        )
      )
    ).data,
    "descr",
    {}
  ),
  local!locations: union(
    local!locationData,
    local!locationData
  ),
  local!BUs: index(
    #"SYSTEM_SYSRULES_queryEntity_v1"(
      entity: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3892805",
      fetchtotalcount: false(),
      query: #"SYSTEM_SYSRULES_query"(
        selection: #"SYSTEM_SYSRULES_querySelection"(columns: { #"SYSTEM_SYSRULES_queryColumn"(field: "descr") }),
        paginginfo: #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: 1,
          batchSize: - 1,
          sort: #"SYSTEM_SYSRULES_sortInfo"(field: "descr", ascending: true)
        )
      )
    ).data,
    "descr",
    {}
  ),
  local!jobFunctions: index(
    #"SYSTEM_SYSRULES_queryEntity_v1"(
